/** Types for the query editor and saved queries */

export interface SavedQuery {
  name: string;
  folder: string;
  path: string;
  description: string;
  sql: string;
  readonly: boolean;
}

export interface QueryResult {
  columns: string[];
  rows: Record<string, unknown>[];
  duration_ms: number;
  row_count: number;
}

export interface QueryError {
  message: string;
  line?: number;
  column?: number;
}

export interface QueryExecution {
  sql: string;
  result: QueryResult | null;
  error: QueryError | null;
  executed_at: string;
}

import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react";
import type {
  SessionSummary,
  SessionSummaryDetail,
  SessionDetail,
  SessionBlock,
  SavedQuery,
  QueryResult,
  Annotation,
  AnnotationListRow,
  SessionAnnotationsResponse,
  SyncReport,
} from "../types";
import {
  decodeSessionBlocks,
  decodeSessionDetail,
  decodeSessionSummaries,
  decodeSessionSummaryDetail,
} from "./sessionProtoAdapters";
import {
  buildCreateAnnotationBody,
  buildSyncAnnotationsBody,
  buildUpdateAnnotationBody,
  decodeAnnotation,
  decodeAnnotationRows,
  decodeSessionAnnotations,
  decodeSyncReport,
  decodeUpdateStatus,
} from "./annotationProtoAdapters";
import {
  decodePresets,
  decodeSavedQueries,
  decodeSavedQuery,
} from "./queryProtoAdapters";

export const minitraceApi = createApi({
  reducerPath: "minitraceApi",
  baseQuery: fetchBaseQuery({ baseUrl: "/api" }),
  tagTypes: ["Sessions", "Queries", "Annotations"],
  endpoints: (builder) => ({
    // ── sessions ─────────────────────────────────
    getSessions: builder.query<SessionSummary[], void>({
      query: () => "v2/sessions",
      transformResponse: decodeSessionSummaries,
      providesTags: ["Sessions"],
    }),

    getSession: builder.query<SessionDetail, string>({
      query: (id) => `v2/sessions/${id}`,
      transformResponse: decodeSessionDetail,
    }),

    getSessionSummary: builder.query<SessionSummaryDetail, string>({
      query: (id) => `v2/sessions/${id}/summary`,
      transformResponse: decodeSessionSummaryDetail,
    }),

    getSessionBlocks: builder.query<SessionBlock[], string>({
      query: (id) => `v2/sessions/${id}/blocks`,
      transformResponse: decodeSessionBlocks,
    }),

    // ── queries ──────────────────────────────────
    executeQuery: builder.mutation<QueryResult, { sql: string }>({
      query: (body) => ({ url: "query", method: "POST", body }),
    }),

    getPresets: builder.query<SavedQuery[], void>({
      query: () => "v2/presets",
      transformResponse: decodePresets,
    }),

    getSavedQueries: builder.query<SavedQuery[], void>({
      query: () => "v2/queries",
      transformResponse: decodeSavedQueries,
      providesTags: ["Queries"],
    }),

    saveQuery: builder.mutation<
      SavedQuery,
      { name: string; folder: string; description: string; sql: string }
    >({
      query: (body) => ({ url: "v2/queries", method: "POST", body }),
      transformResponse: decodeSavedQuery,
      invalidatesTags: ["Queries"],
    }),

    // ── annotations ────────────────────────────────
    getSessionAnnotations: builder.query<SessionAnnotationsResponse, string>({
      query: (sessionId) => `v2/sessions/${sessionId}/annotations`,
      transformResponse: decodeSessionAnnotations,
      providesTags: (_result, _error, sessionId) => [
        { type: "Annotations", id: sessionId },
      ],
    }),

    getAnnotations: builder.query<AnnotationListRow[], void>({
      query: () => "v2/annotations",
      transformResponse: decodeAnnotationRows,
      providesTags: [{ type: "Annotations" }],
    }),

    createAnnotation: builder.mutation<
      Annotation,
      { session_id: string; category: string; title: string; detail?: string; scope_type?: string; target_id?: string; tags?: string[] }
    >({
      query: ({ session_id, ...body }) => ({
        url: `v2/sessions/${session_id}/annotations`,
        method: "POST",
        body: buildCreateAnnotationBody(body),
      }),
      transformResponse: decodeAnnotation,
      invalidatesTags: (_result, _error, { session_id }) => [
        { type: "Annotations", id: session_id },
      ],
    }),

    updateAnnotation: builder.mutation<
      { id: string; status: string },
      { id: string; patch: Record<string, unknown> }
    >({
      query: ({ id, patch }) => ({
        url: `v2/annotations/${id}`,
        method: "PUT",
        body: buildUpdateAnnotationBody(patch),
      }),
      transformResponse: decodeUpdateStatus,
      invalidatesTags: (_result, _error, { id: _annotationId }) => [
        { type: "Annotations" },
      ],
    }),

    deleteAnnotation: builder.mutation<void, { id: string; session_id: string }>({
      query: ({ id }) => ({ url: `v2/annotations/${id}`, method: "DELETE" }),
      transformResponse: () => undefined,
      invalidatesTags: (_result, _error, { session_id }) => [
        { type: "Annotations", id: session_id },
      ],
    }),

    syncAnnotations: builder.mutation<SyncReport, { session_id?: string; dry_run?: boolean }>({
      query: (body = {}) => ({ url: "v2/annotations/sync", method: "POST", body: buildSyncAnnotationsBody(body) }),
      transformResponse: decodeSyncReport,
      invalidatesTags: [{ type: "Annotations" }],
    }),
  }),
});

export const {
  useGetSessionsQuery,
  useGetSessionQuery,
  useGetSessionSummaryQuery,
  useGetSessionBlocksQuery,
  useExecuteQueryMutation,
  useGetPresetsQuery,
  useGetSavedQueriesQuery,
  useSaveQueryMutation,
  useGetSessionAnnotationsQuery,
  useGetAnnotationsQuery,
  useCreateAnnotationMutation,
  useUpdateAnnotationMutation,
  useDeleteAnnotationMutation,
  useSyncAnnotationsMutation,
} = minitraceApi;

import { useEffect, useMemo, useState } from "react";
import { useNavigate, useSearchParams } from "react-router";
import { useSelector, useDispatch } from "react-redux";
import {
  useExecuteQueryMutation,
  useGetPresetsQuery,
  useGetSavedQueriesQuery,
  useSaveQueryMutation,
} from "../api/minitrace";
import { QueryEditor } from "../components/QueryEditor";
import type { SavedQuery } from "../types";
import type { RootState, AppDispatch } from "../store";
import { setQuerySql, openQueryForSession } from "../store";

type QuerySourceKind = "preset" | "saved";

interface ActiveQuerySource {
  kind: QuerySourceKind;
  path: string;
}

export function QueryEditorPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const dispatch = useDispatch<AppDispatch>();
  const { queryEditorSql } = useSelector((state: RootState) => state.ui);
  const [activeSource, setActiveSource] = useState<ActiveQuerySource | null>(null);
  const [lastLoadedSql, setLastLoadedSql] = useState<string | null>(null);
  const [externalUpdateAvailable, setExternalUpdateAvailable] = useState(false);

  const presetPollingInterval = activeSource?.kind === "preset" ? 3000 : 15000;
  const savedPollingInterval = activeSource?.kind === "saved" ? 3000 : 15000;

  const { data: presets = [] } = useGetPresetsQuery(undefined, {
    pollingInterval: presetPollingInterval,
    skipPollingIfUnfocused: true,
    refetchOnFocus: true,
    refetchOnReconnect: true,
  });
  const { data: savedQueries = [] } = useGetSavedQueriesQuery(undefined, {
    pollingInterval: savedPollingInterval,
    skipPollingIfUnfocused: true,
    refetchOnFocus: true,
    refetchOnReconnect: true,
  });
  const [executeQuery, { data: queryResult, error: queryError, isLoading }] =
    useExecuteQueryMutation();
  const [saveQuery] = useSaveQueryMutation();

  const activeSourceQuery = useMemo(() => {
    if (!activeSource) {
      return null;
    }

    const queries = activeSource.kind === "preset" ? presets : savedQueries;
    return queries.find((query) => query.path === activeSource.path) ?? null;
  }, [activeSource, presets, savedQueries]);

  // If ?session=xxx is in the URL, populate the editor
  useEffect(() => {
    const sessionId = searchParams.get("session");
    if (sessionId) {
      setActiveSource(null);
      setLastLoadedSql(null);
      setExternalUpdateAvailable(false);
      dispatch(openQueryForSession(sessionId));
    }
  }, [searchParams, dispatch]);

  useEffect(() => {
    if (!activeSource || !activeSourceQuery) {
      return;
    }

    const latestSql = activeSourceQuery.sql;
    if (lastLoadedSql === null) {
      setLastLoadedSql(latestSql);
      return;
    }

    if (latestSql === lastLoadedSql) {
      if (queryEditorSql === latestSql && externalUpdateAvailable) {
        setExternalUpdateAvailable(false);
      }
      return;
    }

    if (queryEditorSql === lastLoadedSql) {
      dispatch(setQuerySql(latestSql));
      setLastLoadedSql(latestSql);
      setExternalUpdateAvailable(false);
      return;
    }

    setExternalUpdateAvailable(true);
  }, [
    activeSource,
    activeSourceQuery,
    dispatch,
    externalUpdateAvailable,
    lastLoadedSql,
    queryEditorSql,
  ]);

  const handleSelectQuery = (kind: QuerySourceKind) => (query: SavedQuery) => {
    setActiveSource({ kind, path: query.path });
    setLastLoadedSql(query.sql);
    setExternalUpdateAvailable(false);
    dispatch(setQuerySql(query.sql));
  };

  const handleSqlChange = (sql: string) => {
    dispatch(setQuerySql(sql));

    if (activeSourceQuery && sql === activeSourceQuery.sql) {
      setLastLoadedSql(activeSourceQuery.sql);
      setExternalUpdateAvailable(false);
    }
  };

  const handleReloadSource = () => {
    if (!activeSourceQuery) {
      return;
    }

    dispatch(setQuerySql(activeSourceQuery.sql));
    setLastLoadedSql(activeSourceQuery.sql);
    setExternalUpdateAvailable(false);
  };

  return (
    <QueryEditor
      sql={queryEditorSql}
      onSqlChange={handleSqlChange}
      onExecute={(s) => executeQuery({ sql: s })}
      onSave={(s) =>
        saveQuery({
          name: `query-${Date.now()}`,
          folder: "my-queries",
          description: "",
          sql: s,
        })
      }
      onSelectQuery={(query, kind) => handleSelectQuery(kind)(query)}
      onReloadSource={handleReloadSource}
      onClickSessionId={(id) => navigate(`/sessions/${id}`)}
      presets={presets}
      savedQueries={savedQueries}
      result={queryResult ?? null}
      error={
        queryError && "data" in queryError
          ? ((queryError.data as { error?: { message: string } })?.error ?? null)
          : null
      }
      isLoading={isLoading}
      sourceStatus={
        activeSource
          ? {
              label: activeSource.kind === "preset" ? "Preset file" : "Saved query file",
              path: activeSource.path,
              missing: activeSourceQuery === null,
              externalUpdateAvailable,
            }
          : null
      }
    />
  );
}

import Box from "@mui/material/Box";
import List from "@mui/material/List";
import ListItemButton from "@mui/material/ListItemButton";
import ListItemIcon from "@mui/material/ListItemIcon";
import ListItemText from "@mui/material/ListItemText";
import ListSubheader from "@mui/material/ListSubheader";
import Typography from "@mui/material/Typography";
import Tooltip from "@mui/material/Tooltip";
import FolderIcon from "@mui/icons-material/Folder";
import DescriptionIcon from "@mui/icons-material/Description";
import StarIcon from "@mui/icons-material/Star";
import type { SavedQuery } from "../../types";

interface QuerySidebarProps {
  presets: SavedQuery[];
  savedQueries: SavedQuery[];
  onSelect: (query: SavedQuery, kind: "preset" | "saved") => void;
}

function groupByFolder(queries: SavedQuery[]) {
  const groups: Record<string, SavedQuery[]> = {};
  for (const q of queries) {
    const folder = q.folder || "ungrouped";
    if (!groups[folder]) groups[folder] = [];
    groups[folder].push(q);
  }
  return groups;
}

export function QuerySidebar({
  presets,
  savedQueries,
  onSelect,
}: QuerySidebarProps) {
  const presetGroups = groupByFolder(presets);
  const savedGroups = groupByFolder(savedQueries);

  return (
    <Box
      data-part="query-sidebar"
      sx={{
        width: 240,
        borderRight: "1px solid",
        borderColor: "divider",
        overflow: "auto",
        bgcolor: "background.default",
      }}
    >
      <Typography variant="overline" sx={{ px: 2, pt: 2, display: "block" }}>
        Presets
      </Typography>
      {Object.entries(presetGroups).map(([folder, queries]) => (
        <List
          key={folder}
          dense
          subheader={
            <ListSubheader
              sx={{
                bgcolor: "transparent",
                lineHeight: "28px",
                display: "flex",
                alignItems: "center",
                gap: 0.5,
              }}
            >
              <FolderIcon sx={{ fontSize: 14 }} />
              {folder}
            </ListSubheader>
          }
        >
          {queries.map((q) => (
            <Tooltip key={q.path} title={q.description} placement="right" arrow>
              <ListItemButton
                onClick={() => onSelect(q, "preset")}
                sx={{ py: 0.25, pl: 4 }}
              >
                <ListItemIcon sx={{ minWidth: 28 }}>
                  <DescriptionIcon sx={{ fontSize: 14, color: "text.secondary" }} />
                </ListItemIcon>
                <ListItemText
                  primary={q.name}
                  primaryTypographyProps={{
                    variant: "body2",
                    sx: { fontFamily: "monospace", fontSize: "0.75rem" },
                  }}
                />
              </ListItemButton>
            </Tooltip>
          ))}
        </List>
      ))}

      <Typography variant="overline" sx={{ px: 2, pt: 2, display: "block" }}>
        Saved
      </Typography>
      {Object.entries(savedGroups).map(([folder, queries]) => (
        <List
          key={folder}
          dense
          subheader={
            <ListSubheader
              sx={{
                bgcolor: "transparent",
                lineHeight: "28px",
                display: "flex",
                alignItems: "center",
                gap: 0.5,
              }}
            >
              <FolderIcon sx={{ fontSize: 14 }} />
              {folder}
            </ListSubheader>
          }
        >
          {queries.map((q) => (
            <Tooltip key={q.path} title={q.description} placement="right" arrow>
              <ListItemButton
                onClick={() => onSelect(q, "saved")}
                sx={{ py: 0.25, pl: 4 }}
              >
                <ListItemIcon sx={{ minWidth: 28 }}>
                  <StarIcon sx={{ fontSize: 14, color: "primary.main" }} />
                </ListItemIcon>
                <ListItemText
                  primary={q.name}
                  primaryTypographyProps={{
                    variant: "body2",
                    sx: { fontFamily: "monospace", fontSize: "0.75rem" },
                  }}
                />
              </ListItemButton>
            </Tooltip>
          ))}
        </List>
      ))}
    </Box>
  );
