107	    setLastLoadedSql(query.sql);
108	    setExternalUpdateAvailable(false);
109	    dispatch(setQuerySql(query.sql));
110	  };
111	
112	  const handleSqlChange = (sql: string) => {
113	    dispatch(setQuerySql(sql));
114	
115	    if (activeSourceQuery && sql === activeSourceQuery.sql) {
116	      setLastLoadedSql(activeSourceQuery.sql);
117	      setExternalUpdateAvailable(false);
118	    }
119	  };
120	
121	  const handleReloadSource = () => {
122	    if (!activeSourceQuery) {
123	      return;
124	    }
125	
126	    dispatch(setQuerySql(activeSourceQuery.sql));
127	    setLastLoadedSql(activeSourceQuery.sql);
128	    setExternalUpdateAvailable(false);
129	  };
130	
131	  return (
132	    <QueryEditor
133	      sql={queryEditorSql}
134	      onSqlChange={handleSqlChange}
135	      onExecute={(s) => executeQuery({ sql: s })}
136	      onSave={(s) =>
137	        saveQuery({
138	          name: `query-${Date.now()}`,
139	          folder: "my-queries",
140	          description: "",
141	          sql: s,
142	        })
143	      }
144	      onSelectQuery={(query, kind) => handleSelectQuery(kind)(query)}
145	      onReloadSource={handleReloadSource}
146	      onClickSessionId={(id) => navigate(`/sessions/${id}`)}
147	      presets={presets}
148	      savedQueries={savedQueries}
149	      result={queryResult ?? null}
150	      error={
151	        queryError && "data" in queryError
152	          ? ((queryError.data as { error?: { message: string } })?.error ?? null)
153	          : null
154	      }
155	      isLoading={isLoading}
156	      sourceStatus={
157	        activeSource
158	          ? {
159	              label: activeSource.kind === "preset" ? "Preset file" : "Saved query file",
160	              path: activeSource.path,
161	              missing: activeSourceQuery === null,
162	              externalUpdateAvailable,
163	            }
164	          : null
165	      }
166	    />
167	  );
168	}

