100	func ExpandArchiveGlobs(archiveGlobs []string) ([]string, error) {
101		normalizedGlobs := normalizeStringList(archiveGlobs)
102		if len(normalizedGlobs) == 0 {
103			return nil, fmt.Errorf("archive glob is required")
104		}
105	
106		resolvedFiles := make([]string, 0)
107		seenFiles := make(map[string]struct{})
108	
109		for _, archiveGlob := range normalizedGlobs {
110			files, err := filepath.Glob(archiveGlob)
111			if err != nil {
112				return nil, fmt.Errorf("expanding archive glob %q: %w", archiveGlob, err)
113			}
114			for _, filePath := range files {
115				absPath, err := filepath.Abs(filePath)
116				if err != nil {
117					return nil, fmt.Errorf("resolving absolute path for %s: %w", filePath, err)
118				}
119				if _, ok := seenFiles[absPath]; ok {
120					continue
121				}
122				seenFiles[absPath] = struct{}{}
123				resolvedFiles = append(resolvedFiles, absPath)
124			}
125		}
126	
127		if len(resolvedFiles) == 0 {
128			return nil, fmt.Errorf("archive globs matched no files: %s", strings.Join(normalizedGlobs, ", "))
129		}
130	
131		return resolvedFiles, nil
132	}
