172	func RunIntoProcessor(ctx context.Context, conn *sql.Conn, sqlText string, gp middlewares.Processor) error {
173		rows, err := conn.QueryContext(ctx, sqlText)
174		if err != nil {
175			return fmt.Errorf("executing query: %w", err)
176		}
177		defer func() { _ = rows.Close() }()
178	
179		columns, err := rows.Columns()
180		if err != nil {
181			return fmt.Errorf("reading query columns: %w", err)
182		}
183	
184		for rows.Next() {
185			values := make([]any, len(columns))
186			scanArgs := make([]any, len(columns))
187			for i := range scanArgs {
188				scanArgs[i] = &values[i]
189			}
190			if err := rows.Scan(scanArgs...); err != nil {
191				return fmt.Errorf("scanning query row: %w", err)
192			}
193	
194			rowParts := make([]types.MapRowPair, 0, len(columns))
195			for i, column := range columns {
196				rowParts = append(rowParts, types.MRP(column, NormalizeValue(values[i])))
197			}
198			if err := gp.AddRow(ctx, types.NewRow(rowParts...)); err != nil {
199				return err
200			}
201		}
202		if err := rows.Err(); err != nil {
203			return fmt.Errorf("iterating query rows: %w", err)
204		}
205		return nil
206	}
