    28	  const [lastLoadedSql, setLastLoadedSql] = useState<string | null>(null);
    29	  const [externalUpdateAvailable, setExternalUpdateAvailable] = useState(false);
    30	
    31	  const presetPollingInterval = activeSource?.kind === "preset" ? 3000 : 15000;
    32	  const savedPollingInterval = activeSource?.kind === "saved" ? 3000 : 15000;
    33	
    34	  const { data: presets = [] } = useGetPresetsQuery(undefined, {
    35	    pollingInterval: presetPollingInterval,
    36	    skipPollingIfUnfocused: true,
    37	    refetchOnFocus: true,
    38	    refetchOnReconnect: true,
    39	  });
    40	  const { data: savedQueries = [] } = useGetSavedQueriesQuery(undefined, {
    41	    pollingInterval: savedPollingInterval,
    42	    skipPollingIfUnfocused: true,
    43	    refetchOnFocus: true,
    44	    refetchOnReconnect: true,
    45	  });
    46	  const [executeQuery, { data: queryResult, error: queryError, isLoading }] =
    47	    useExecuteQueryMutation();
    48	  const [saveQuery] = useSaveQueryMutation();
    49	
    50	  const activeSourceQuery = useMemo(() => {
    51	    if (!activeSource) {
    52	      return null;
    53	    }
    54	
    55	    const queries = activeSource.kind === "preset" ? presets : savedQueries;
    56	    return queries.find((query) => query.path === activeSource.path) ?? null;
    57	  }, [activeSource, presets, savedQueries]);
    58	
    59	  // If ?session=xxx is in the URL, populate the editor
    60	  useEffect(() => {
    61	    const sessionId = searchParams.get("session");
    62	    if (sessionId) {
    63	      setActiveSource(null);
    64	      setLastLoadedSql(null);
    65	      setExternalUpdateAvailable(false);
    66	      dispatch(openQueryForSession(sessionId));
    67	    }
    68	  }, [searchParams, dispatch]);
    69	
    70	  useEffect(() => {
    71	    if (!activeSource || !activeSourceQuery) {
    72	      return;
    73	    }
    74	
    75	    const latestSql = activeSourceQuery.sql;
    76	    if (lastLoadedSql === null) {
    77	      setLastLoadedSql(latestSql);
    78	      return;
    79	    }
    80	
    81	    if (latestSql === lastLoadedSql) {
    82	      if (queryEditorSql === latestSql && externalUpdateAvailable) {
    83	        setExternalUpdateAvailable(false);
    84	      }
