    90	      setLastLoadedSql(latestSql);
    91	      setExternalUpdateAvailable(false);
    92	      return;
    93	    }
    94	
    95	    setExternalUpdateAvailable(true);
    96	  }, [
    97	    activeSource,
    98	    activeSourceQuery,
    99	    dispatch,
