69	func normalizeRepositoryPaths(paths []string) []string {
70		ret := make([]string, 0, len(paths))
71		seen := map[string]struct{}{}
72	
73		for _, path := range paths {
74			path = strings.TrimSpace(path)
75			if path == "" {
76				continue
77			}
78			if _, ok := seen[path]; ok {
79				continue
80			}
81			seen[path] = struct{}{}
82			ret = append(ret, path)
83		}
84	
85		return ret
