 36	type SqlCommandSpec struct {
 37		Name       string                 `yaml:"name"`
 38		Short      string                 `yaml:"short"`
 39		Long       string                 `yaml:"long,omitempty"`
 40		Layout     []*layout.Section      `yaml:"layout,omitempty"`
 41		Flags      []*fields.Definition   `yaml:"flags,omitempty"`
 42		Arguments  []*fields.Definition   `yaml:"arguments,omitempty"`
 43		Tags       []string               `yaml:"tags,omitempty"`
 44		Metadata   map[string]interface{} `yaml:"metadata,omitempty"`
 45		Query      string                 `yaml:"query"`
 46		SubQueries map[string]string      `yaml:"subqueries,omitempty"`
 47	}
 48	
 49	func (s *SqlCommandSpec) Validate() error {
 50		if strings.TrimSpace(s.Name) == "" {
 51			return errors.New("sql command spec is missing name")
 52		}
 53		if strings.TrimSpace(s.Short) == "" {
 54			return errors.Errorf("sql command spec %q is missing short description", s.Name)
 55		}
 56		if strings.TrimSpace(s.Query) == "" {
 57			return errors.Errorf("sql command spec %q is missing query body", s.Name)
 58		}
 59		return nil
 60	}
 61	
 62	type SqlCommandCompiler struct {
 63		DBConnectionFactory clay_sql.DBConnectionFactory
 64	}
 65	
 66	func (c *SqlCommandCompiler) Compile(
 67		spec *SqlCommandSpec,
 68		options ...cmds.CommandDescriptionOption,
 69	) (*SqlCommand, error) {
 70		if spec == nil {
 71			return nil, errors.New("sql command spec is nil")
 72		}
 73		if err := spec.Validate(); err != nil {
 74			return nil, err
 75		}
 76	
 77		cmd, err := NewSqlCommand(
 78			cmds.NewCommandDescription(spec.Name),
 79			WithDbConnectionFactory(c.DBConnectionFactory),
 80			WithQuery(spec.Query),
 81			WithSubQueries(spec.SubQueries),
 82		)
 83		if err != nil {
 84			return nil, err
 85		}
 86	
 87		normalizedFlags := normalizeOptionalBoolFlags(spec.Flags)
 88	
 89		options_ := []cmds.CommandDescriptionOption{
 90			cmds.WithShort(spec.Short),
 91			cmds.WithLong(spec.Long),
 92			cmds.WithFlags(normalizedFlags...),
 93			cmds.WithArguments(spec.Arguments...),
 94			cmds.WithTags(spec.Tags...),
 95			cmds.WithMetadata(spec.Metadata),
 96			cmds.WithLayout(&layout.Layout{
 97				Sections: spec.Layout,
 98			}),
 99		}
100		options_ = append(options_, options...)
101	
102		for _, option := range options_ {
103			option(cmd.Description())
104		}
105	
106		if !cmd.IsValid() {
107			return nil, errors.New("invalid sql command")
108		}
109	
110		return cmd, nil
111	}
112	
113	func normalizeOptionalBoolFlags(flags []*fields.Definition) []*fields.Definition {
114		if len(flags) == 0 {
115			return nil
116		}
117	
118		ret := make([]*fields.Definition, 0, len(flags))
119		for _, flag := range flags {
120			if flag == nil {
121				ret = append(ret, nil)
122				continue
123			}
124	
125			cloned := flag.Clone()
126			if cloned.Type == fields.TypeBool && !cloned.Required && cloned.Default == nil {
127				defaultValue := interface{}(false)
128				cloned.Default = &defaultValue
129			}
130			ret = append(ret, cloned)
131		}
132	
133		return ret
134	}
