136	func ParseSQLFileSpec(path string, contents []byte) (*SqlCommandSpec, error) {
137		metadataText, body, err := splitSqletonSQLPreamble(contents)
138		if err != nil {
139			return nil, errors.Wrapf(err, "parse sqleton sql preamble: %s", path)
140		}
141	
142		spec := &SqlCommandSpec{}
143		decoder := yaml.NewDecoder(strings.NewReader(metadataText))
144		if err := decoder.Decode(spec); err != nil {
145			return nil, errors.Wrapf(err, "decode sqleton sql metadata: %s", path)
146		}
147	
148		if len(spec.SubQueries) > 0 {
149			return nil, errors.Errorf("sql command spec %q uses subqueries in metadata; inline them with SQL or CTEs instead", path)
150		}
151	
152		spec.Query = strings.TrimSpace(body)
153		if err := spec.Validate(); err != nil {
154			return nil, errors.Wrapf(err, "validate sqleton sql command: %s", path)
155		}
156		return spec, nil
157	}
158	
159	func splitSqletonSQLPreamble(contents []byte) (string, string, error) {
160		s := strings.TrimLeft(string(contents), "\ufeff\r\n\t ")
161		if !strings.HasPrefix(s, "/*") {
162			return "", "", errors.New("missing sqleton sql preamble")
163		}
164	
165		end := strings.Index(s, "*/")
166		if end == -1 {
167			return "", "", errors.New("unterminated sqleton sql preamble")
168		}
169	
170		raw := strings.TrimSpace(s[2:end])
171		if !strings.HasPrefix(raw, "sqleton") {
172			return "", "", errors.New("invalid sqleton sql preamble marker")
173		}
174	
175		metadata := strings.TrimSpace(strings.TrimPrefix(raw, "sqleton"))
176		body := strings.TrimSpace(s[end+2:])
177		if metadata == "" {
178			return "", "", errors.New("empty sqleton sql preamble metadata")
179		}
180		if body == "" {
181			return "", "", errors.New("empty sqleton sql query body")
182		}
183	
184		return metadata, body, nil
185	}
186	
187	func LooksLikeSqletonSQLCommand(contents []byte) bool {
188		s := strings.TrimLeft(string(contents), "\ufeff\r\n\t ")
189		if !strings.HasPrefix(s, "/*") {
190			return false
191		}
192	
193		end := strings.Index(s, "*/")
194		if end == -1 {
195			return false
196		}
197	
198		raw := strings.TrimSpace(s[2:end])
199		return strings.HasPrefix(raw, "sqleton")
200	}
201	
202	func MarshalSpecToSQLFile(spec *SqlCommandSpec) (string, error) {
203		if spec == nil {
204			return "", errors.New("sql command spec is nil")
205		}
206		if err := spec.Validate(); err != nil {
207			return "", err
208		}
209		if len(spec.SubQueries) > 0 {
210			return "", errors.New("sql command spec with subqueries cannot be marshaled to a .sql file")
211		}
212	
213		metadata := &SqlCommandSpec{
214			Name:      spec.Name,
215			Short:     spec.Short,
216			Long:      spec.Long,
217			Layout:    spec.Layout,
218			Flags:     spec.Flags,
219			Arguments: spec.Arguments,
220			Tags:      spec.Tags,
221			Metadata:  spec.Metadata,
222		}
223	
224		var buf bytes.Buffer
225		encoder := yaml.NewEncoder(&buf)
226		encoder.SetIndent(2)
227		if err := encoder.Encode(metadata); err != nil {
228			return "", errors.Wrap(err, "encode sqleton sql metadata")
229		}
230		if err := encoder.Close(); err != nil {
231			return "", errors.Wrap(err, "close sqleton sql metadata encoder")
232		}
233	
234		metadataText := strings.TrimSpace(buf.String())
235		query := strings.TrimSpace(spec.Query)
236	
237		var ret strings.Builder
238		ret.WriteString("/* sqleton\n")
239		ret.WriteString(metadataText)
240		ret.WriteString("\n*/\n")
241		ret.WriteString(query)
242		ret.WriteString("\n")
243		return ret.String(), nil
244	}
245	
246	func ParseSQLFileSpecFromReader(path string, r io.Reader) (*SqlCommandSpec, error) {
247		contents, err := io.ReadAll(r)
248		if err != nil {
249			return nil, errors.Wrapf(err, "read sqleton sql command: %s", path)
250		}
251		return ParseSQLFileSpec(path, contents)
252	}

260	func buildSessionIndex(archiveGlobs []string) (map[string]string, error) {
261		files, err := queryengine.ExpandArchiveGlobs(archiveGlobs)
262		if err != nil {
263			return nil, err
264		}
265	
266		index := make(map[string]string, len(files))
267		for _, filePath := range files {
268			sessionID, err := readSessionIDFromArchive(filePath)
269			if err != nil {
270				return nil, err
271			}
272			if previous, ok := index[sessionID]; ok {
273				return nil, errors.Errorf("duplicate session ID %q found in %s and %s", sessionID, previous, filePath)
274			}
275			index[sessionID] = filePath
276		}
277		if len(index) == 0 {
278			return nil, errors.Errorf("archive globs matched no .minitrace.json files")
279		}
280		return index, nil
281	}
