301	func validateReadOnlyQuery(sqlText string) error {
302		normalized, err := normalizeQueryForValidation(sqlText)
303		if err != nil {
304			return err
305		}
306	
307		allowedPrefixes := []string{"select", "with", "explain", "describe", "show"}
308		lower := strings.ToLower(normalized)
309		for _, prefix := range allowedPrefixes {
310			if strings.HasPrefix(lower, prefix) {
311				return nil
312			}
313		}
314	
315		return errors.New("only read-only SELECT, WITH, EXPLAIN, DESCRIBE, and SHOW queries are allowed")
