func TestMinitraceCommandSpecValidateVerb(t *testing.T) {
	spec := &MinitraceCommandSpec{
		Name:  "session-list",
		Short: "List sessions",
		Query: "select 1",
		Kind:  MinitraceCommandVerb,
	}

	if err := spec.Validate(); err != nil {
