	}})
	if err != nil {
		t.Fatalf("LoadCatalog returned error: %v", err)
	}

	cmd := catalog.ByPath["core/session-list.sql"]
	if cmd == nil {
		t.Fatalf("missing derived path entry")
	}
	if cmd.Folder != "core" {
		t.Fatalf("Folder = %q, want core", cmd.Folder)
	}
	if cmd.Path != "core/session-list.sql" {
